CREATE TABLE service_accounts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),channel TEXT NOT NULL CHECK(channel IN ('whatsapp','instagram','tiktok','snapchat')),provider_id TEXT NOT NULL,label TEXT NOT NULL,api_version TEXT NOT NULL,token_ref TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'unverified',scopes TEXT NOT NULL DEFAULT '[]',expires_at BIGINT,checked_at TEXT,last_inbound_at TEXT,last_outbound_at TEXT,approval_reference TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,UNIQUE(channel,provider_id),UNIQUE(id,tenant_id));
CREATE TABLE service_identities(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,provider_user_id TEXT NOT NULL,name TEXT NOT NULL,customer_id TEXT,verified_at TEXT,created_at TEXT NOT NULL,UNIQUE(account_id,provider_user_id),UNIQUE(id,tenant_id),FOREIGN KEY(account_id,tenant_id) REFERENCES service_accounts(id,tenant_id));
CREATE TABLE service_settings(tenant_id TEXT PRIMARY KEY REFERENCES tenants(id),settings TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE service_tickets(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,identity_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',category TEXT NOT NULL DEFAULT 'general',priority TEXT NOT NULL DEFAULT 'normal',team TEXT NOT NULL DEFAULT 'support',branch TEXT NOT NULL DEFAULT '',language TEXT NOT NULL DEFAULT 'ar',source TEXT NOT NULL DEFAULT '',assignee_id TEXT REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1,last_customer_at BIGINT NOT NULL DEFAULT 0,first_human_at BIGINT,first_resolved_at BIGINT,resolved_at BIGINT,resolution_code TEXT NOT NULL DEFAULT '',summary TEXT NOT NULL DEFAULT '',automation_paused INTEGER NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,UNIQUE(id,tenant_id),FOREIGN KEY(identity_id,tenant_id) REFERENCES service_identities(id,tenant_id));
CREATE TABLE service_messages(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,ticket_id TEXT NOT NULL,account_id TEXT NOT NULL,provider_id TEXT,direction TEXT NOT NULL CHECK(direction IN ('in','out','note')),kind TEXT NOT NULL DEFAULT 'text',body TEXT NOT NULL,status TEXT NOT NULL,author_id TEXT REFERENCES users(id),occurred_at BIGINT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(account_id,provider_id),UNIQUE(id,tenant_id),FOREIGN KEY(ticket_id,tenant_id) REFERENCES service_tickets(id,tenant_id),FOREIGN KEY(account_id,tenant_id) REFERENCES service_accounts(id,tenant_id));
CREATE TABLE service_events(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES service_accounts(id),event_key TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',received_at BIGINT NOT NULL,processed_at BIGINT,UNIQUE(account_id,event_key));
CREATE TABLE service_outbox(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,message_id TEXT NOT NULL,request_key TEXT NOT NULL,payload_hash TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,claimed_at BIGINT,error TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL,UNIQUE(tenant_id,request_key),FOREIGN KEY(message_id,tenant_id) REFERENCES service_messages(id,tenant_id));
CREATE TABLE service_status_history(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES service_accounts(id),provider_id TEXT NOT NULL,status TEXT NOT NULL,occurred_at BIGINT NOT NULL,UNIQUE(account_id,provider_id,status,occurred_at));
CREATE TABLE service_consents(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,identity_id TEXT NOT NULL,purpose TEXT NOT NULL,source TEXT NOT NULL,captured_at BIGINT NOT NULL,revoked_at BIGINT,FOREIGN KEY(identity_id,tenant_id) REFERENCES service_identities(id,tenant_id));
CREATE TABLE service_templates(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,name TEXT NOT NULL,language TEXT NOT NULL,status TEXT NOT NULL,components TEXT NOT NULL,checked_at BIGINT NOT NULL,UNIQUE(account_id,name,language),FOREIGN KEY(account_id,tenant_id) REFERENCES service_accounts(id,tenant_id));
CREATE TABLE service_replies(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),title TEXT NOT NULL,body TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE service_ratings(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,ticket_id TEXT NOT NULL UNIQUE,score INTEGER NOT NULL CHECK(score BETWEEN 1 AND 5),source TEXT NOT NULL,created_at BIGINT NOT NULL,FOREIGN KEY(ticket_id,tenant_id) REFERENCES service_tickets(id,tenant_id));
CREATE TABLE service_identity_links(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,left_id TEXT NOT NULL,right_id TEXT NOT NULL,evidence TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at BIGINT NOT NULL,revoked_at BIGINT,FOREIGN KEY(left_id,tenant_id) REFERENCES service_identities(id,tenant_id),FOREIGN KEY(right_id,tenant_id) REFERENCES service_identities(id,tenant_id));
CREATE INDEX service_ticket_scope ON service_tickets(tenant_id,status,assignee_id,updated_at);
CREATE INDEX service_message_scope ON service_messages(tenant_id,ticket_id,created_at);
CREATE INDEX service_event_due ON service_events(state,next_attempt);
CREATE INDEX service_outbox_due ON service_outbox(state,next_attempt);
INSERT INTO schema_migrations(version,applied_at) VALUES(3,'2026-11-14T00:00:00+00:00');
CREATE TABLE service_secrets(account_id TEXT PRIMARY KEY REFERENCES service_accounts(id),ciphertext TEXT NOT NULL,issued_at BIGINT NOT NULL);
CREATE TABLE service_oauth_states(state_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES service_accounts(id),user_id TEXT NOT NULL REFERENCES users(id),session_hash TEXT NOT NULL,expires_at BIGINT NOT NULL,consumed_at BIGINT);
CREATE TABLE service_media(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,ticket_id TEXT NOT NULL,object_key TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes BIGINT NOT NULL,sha256 TEXT NOT NULL,scan_state TEXT NOT NULL,created_at BIGINT NOT NULL,FOREIGN KEY(ticket_id,tenant_id) REFERENCES service_tickets(id,tenant_id));
